fn control_flow(
    optional: ?Callback,
    callbacks: []Callback,
    result: anyerror!Callback,
    value: anytype,
) void {
    if (optional) |callback| {
        callback();
    }
    callback();

    if (result) |callback| {
        callback();
    } else |err| {
        consume(err);
    }
    callback();
